def describe_number(num: int) -> str:
    by3 = num % 3 == 0
    by5 = num % 5 == 0
    if by3 and by5:
        return "FizzBuzz"
    if by3:
        return "Fizz"
    if by5:
        return "Buzz"
    return "Normal"

def card_to_value_tuple(card: str) -> tuple:
    # The suit is the last character; the rank is everything before it.
    suit = card[-1]
    rank = card[:-1]
    suit_values = {'S': 1, 'H': 2, 'D': 3, 'C': 4}
    rank_values = {'A': 1, 'J': 11, 'Q': 12, 'K': 13}
    rank_value = rank_values[rank] if rank in rank_values else int(rank)
    return (suit_values[suit], rank_value)

from collections import Counter


def unique_sum_pairs(nums: list, k: int) -> set:
    counts = Counter(nums)
    result = set()
    for a in counts:
        b = k - a
        if a < b and b in counts:
            result.add((a, b))
        elif a == b and counts[a] >= 2:
            # a number can pair with itself only if it occurs at least twice
            result.add((a, a))
    return result

def deinterleave(s: str) -> str:
    # even-index characters first, then the odd-index characters
    return s[::2] + s[1::2]
